window.products.push({"id":639169,"name":"Fender Worldwide 24 in. Barstool 24 in. Black","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/71TDSs0w4BL._AC_SL1500_.jpg","description":"Worldwide 24 in. Barstool 24 in. Black Proper posture is a key element to a productive practice session. Chair arms can force you to contort uncomfortably to keep your instrument in its natural playing position while restricting your ability to move along the neck freely and forcing you into a back-killing hunched playing position. This barstool offers a stable support for your back, while working your core muscles and ensuring you have unhindered access to the entire instrument.","images":["https://m.media-amazon.com/images/I/71TDSs0w4BL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Fender","source_asin":"B0771HH7YJ","category_path":"Home & Kitchen"},"sku":"BM-639169","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B0771HH7YJ","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B0771HH7YJ","price_pending":true,"merchant_ready":false});
