window.products.push({"id":639827,"name":"Kurt Adler 10-inch Fabriche Shopping Santa","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/61O3zpyKR9L._AC_SL1000_.jpg","description":"This Kurt Adler 10-inch Shopping Santa is a fun and festive addition to your holiday or theme party décor. Santa is wearing his traditional red and white Santa suit with his black snow boots and green mittens. In one hand he is holding a gold box wrapped in a red oversized bow and in the other hand he is holding a red bag with a picture of his face on the front. Peeking out of his bag is a red and green striped scarf and a present wrapped in green wrapping paper topped with a gold bow.","images":["https://m.media-amazon.com/images/I/61O3zpyKR9L._AC_SL1000_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Kurt S. Adler","source_asin":"B00BP82X24","category_path":"Home & Kitchen"},"sku":"BM-639827","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00BP82X24","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B00BP82X24","price_pending":true,"merchant_ready":false});
